#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *arcos = malloc((size_t)n * sizeof(long long));
    long long *pos = malloc((size_t)n * sizeof(long long));

    long long total = 0;
    for (int i = 0; i < n; i++) {
        scanf("%lld", &arcos[i]);
        total += arcos[i];
    }

    pos[0] = 0;
    for (int i = 1; i < n; i++)
        pos[i] = pos[i - 1] + arcos[i - 1];

    if (total % 2 != 0) {
        puts("N");
        free(arcos);
        free(pos);
        return 0;
    }

    long long metade = total / 2;
    int pares = 0;

    for (int i = 0; i < n; i++) {
        long long alvo = pos[i] + metade;
        if (alvo >= total) alvo -= total;

        int esquerda = 0, direita = n - 1;
        while (esquerda <= direita) {
            int meio = esquerda + (direita - esquerda) / 2;
            if (pos[meio] == alvo) {
                if (i < meio) pares++;
                break;
            }
            if (pos[meio] < alvo)
                esquerda = meio + 1;
            else
                direita = meio - 1;
        }
    }

    puts(pares >= 2 ? "S" : "N");

    free(arcos);
    free(pos);
    return 0;
}
